func HasProjectWith(preds ...predicate.Project) predicate.LepoShipLocalConfig {
	return predicate.LepoShipLocalConfig(func(s *sql.Selector) {
		step := newProjectStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LepoShipLocalConfig) predicate.LepoShipLocalConfig {
	return predicate.LepoShipLocalConfig(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LepoShipLocalConfig) predicate.LepoShipLocalConfig {
	return predicate.LepoShipLocalConfig(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LepoShipLocalConfig) predicate.LepoShipLocalConfig {
	return predicate.LepoShipLocalConfig(sql.NotPredicates(p))
}
